{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Olsalazine, a salicylate-based molecule, showed only 2.3% systemic availability after a 1 g oral dose in healthy volunteers, demonstrating that this phenolic/aromatic acid class can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Chloramphenicol, a nitroaromatic amide, showed high oral bioavailability in children, indicating that a nitro group and amide linkage alone do not necessarily cause low oral bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Tolcapone, which contains both nitro and phenolic groups, had an absolute oral bioavailability of about 60% in healthy volunteers, showing that these structural features can be compatible with high systemic exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, a lipophilic chlorophenyl amide with saturable absorption, had an absolute oral bioavailability of 31.8% after a 150 mg oral dose, providing a distant high-F example among poorly soluble aromatic amides.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a fully aromatic, lipophilic salicylanilide with a nitro group and two chlorines, closely matching the poorly absorbed niclosamide phenotype. Although several high-bioavailability analogues exist, they are structurally distant and lack the salicylanilide absorption liability. The only directly low-F analogue, olsalazine (2.3% systemic availability), supports poor oral absorption for this phenolic/aromatic acid class. The physicochemical prior is mixed, but the known poor solubility and fully aromatic salicylanilide character outweigh the distant high-F evidence, leading to a low bioavailability prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "The closest low-F analogue, olsalazine, has low Morgan similarity and different ionization behavior.",
    "High-F analogues are structurally distant and do not capture the salicylanilide-specific absorption limitations.",
    "No human pharmacokinetic data for niclosamide were included in the provided evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

